tool_calls:
mkdir -p /lib && cat > /lib/utils.sh <<'EOF'
#!/usr/bin/env bash
# Utility functions

# Reads stdin and converts to uppercase
to_upper() {
    tr '[:lower:]' '[:upper:]'
}

# Takes a filename argument and prints the line count
count_lines() {
    wc -l < "$1"
}

# Takes a filename and prints byte count
file_size() {
    wc -c < "$1"
}
EOF
echo "File created:" && cat /lib/utils.sh

